	export default {
    async asyncData({ $content, params }) {
      try {
        const details = await $content(`overseas-students/en`).fetch();

        return {
          details
        }
      } catch(e) {
        window.location.href = '/404';
      }
		},
		head() {
			if(this.details) {
				return {
					title: this.details.pageTitle,
					meta: [
						{
						hid: 'description',
						name: 'description',
						content: this.details.pageDescription
						}
					],
				}
			}
		}
	}
